'use strict'

import resource from '../resource'
import textManager from '../service/text-manager'
import { createBItem } from './link'
import { GAME_WIDTH, NES_PIXEL, ITEM_RAFT, ITEM_BOOK_OF_MAGIC, ITEM_RED_RING, ITEM_BLUE_RING, ITEM_RING_RED, ITEM_RING_BLUE, ITEM_LADDER, ITEM_MAGICAL_KEY, ITEM_POWER_BRACELET, ITEM_BOW, ITEM_SILVER_ARROW, ITEM_WOODEN_ARROW, ARROW_SILVER, SPRITE_TEXT_COLOR_RED, SPRITE_TEXT_COLOR_WHITE } from '../constant'

// The inventory of the original game (Start): it scrolls down from the top of the screen, pushing the
// screen and the top menu down, and shows the items of the B button. Left / right choose the one on B.
// Positions are those of the original, in NES pixels, doubled for the display
const SCALE = NES_PIXEL
// 3 NES pixels every frame, as in the original
const SCROLL_STEP = 3 * SCALE
const TILE = 8 * SCALE

// The 8 places of the B items (see Inventory.bItems)
const SLOTS_PER_LINE = 4
const SLOTS_X = 132
const SLOTS_Y = 56
const SLOT_WIDTH = 24
const SLOT_HEIGHT = 16
// The place of the bow and arrows holds the arrow and the bow, side by side, either one alone too (measured: arrow
// at x = 176, bow at 184)
const BOW_SLOT = 2
const BOW_SHIFT = 4
// Above the frame, the items that are not used with B (measured in the ROM): the raft and the ladder are 16 NES
// pixels wide, the others 8. x of the left of the item, at y = 32
const PASSIVES_Y = 32
const PASSIVES = [
  [inventory => inventory.raft ? ITEM_RAFT : undefined, 128, true],
  [inventory => inventory.bookOfMagic ? ITEM_BOOK_OF_MAGIC : undefined, 152],
  [inventory => inventory.ring === ITEM_RING_RED ? ITEM_RED_RING : inventory.ring === ITEM_RING_BLUE ? ITEM_BLUE_RING : undefined, 164],
  [inventory => inventory.ladder ? ITEM_LADDER : undefined, 176, true],
  [inventory => inventory.magicalKey ? ITEM_MAGICAL_KEY : undefined, 196],
  [inventory => inventory.powerBracelet ? ITEM_POWER_BRACELET : undefined, 208]
]

// An item is 8 NES pixels wide, in the middle of its 16 pixels sprite (x: its left)
function drawItem (context, name, x, y) {
  resource.getSprite(`item_${name}`)?.draw(context, (x - 4) * SCALE, y * SCALE, 2 * TILE, 2 * TILE)
}

// A blue frame of tiles; x, y in NES pixels, size in tiles
function drawFrame (context, x, y, columns, lines) {
  const draw = (name, column, line) => resource.getSprite(`menu_blue_line_${name}`)?.draw(context, (x + column * 8) * SCALE, (y + line * 8) * SCALE, TILE, TILE)
  for (let column = 1; column < columns - 1; column++) {
    draw('horizontal', column, 0)
    draw('horizontal', column, lines - 1)
  }
  for (let line = 1; line < lines - 1; line++) {
    draw('vertical', 0, line)
    draw('vertical', columns - 1, line)
  }
  draw('corner_north_west', 0, 0)
  draw('corner_north_east', columns - 1, 0)
  draw('corner_south_west', 0, lines - 1)
  draw('corner_south_east', columns - 1, lines - 1)
}

class InventoryMenu {
  constructor (link, height) {
    this.link = link
    this.height = height // Of the screen it covers
    this.offset = 0 // How far down it is
    this.isOpen = false
  }

  // Shown, or scrolling
  get isShown () {
    return this.isOpen || this.offset > 0
  }

  toggle () {
    this.isOpen = !this.isOpen
  }

  // One game step of the scroll
  update () {
    this.offset = this.isOpen ? Math.min(this.height, this.offset + SCROLL_STEP) : Math.max(0, this.offset - SCROLL_STEP)
  }

  // The next item owned, on the left (-1) or on the right (1), goes on B
  move (delta) {
    if (!this.isOpen) {
      return
    }
    const items = this.link.inventory.bItems
    const owned = items.map((name, index) => name ? index : undefined).filter(index => index !== undefined)
    if (owned.length === 0) {
      return
    }
    const current = owned.indexOf(this.selection)
    const next = current === -1 ? owned[0] : owned[(current + delta + owned.length) % owned.length]
    if (next !== this.selection) {
      this.link.itemB = createBItem(items[next])
    }
  }

  // The place of the item on B
  get selection () {
    const index = this.link.itemB ? this.link.inventory.bItems.indexOf(this.link.itemB.name) : -1
    return index === -1 ? undefined : index
  }

  drawTriforce (context) {
    context.save()
    context.lineWidth = SCALE
    for (const [color, inset] of [['#fcbcb0', 0], ['#d82800', 6]]) {
      context.strokeStyle = color
      context.beginPath()
      context.moveTo(128 * SCALE, (112 + inset) * SCALE)
      context.lineTo((176 - 1.7 * inset) * SCALE, (160 - inset / 2) * SCALE)
      context.lineTo((80 + 1.7 * inset) * SCALE, (160 - inset / 2) * SCALE)
      context.closePath()
      context.stroke()
    }
    context.restore()
    textManager.drawLine(context, 'triforce', SPRITE_TEXT_COLOR_RED, 96 * SCALE, 168 * SCALE)
  }

  // Above the top menu, which is drawn `offset` lower
  draw (context) {
    if (this.offset === 0) {
      return
    }
    context.save()
    context.translate(0, this.offset - this.height)
    context.fillStyle = 'black'
    context.fillRect(0, 0, GAME_WIDTH, this.height)

    textManager.drawLine(context, 'inventory', SPRITE_TEXT_COLOR_RED, 32 * SCALE, 32 * SCALE)

    // The item on B
    drawFrame(context, 56, 48, 4, 4)
    if (this.link.itemB) {
      drawItem(context, this.link.itemB.name, 68, 56)
    }
    textManager.drawLine(context, 'use b button', SPRITE_TEXT_COLOR_WHITE, 16 * SCALE, 80 * SCALE)
    textManager.drawLine(context, 'for this', SPRITE_TEXT_COLOR_WHITE, 32 * SCALE, 88 * SCALE)

    // The items not used with B, above the frame
    const inventory = this.link.inventory
    for (const [owned, x, wide] of PASSIVES) {
      const name = owned(inventory)
      if (name) {
        drawItem(context, name, wide ? x + 4 : x, PASSIVES_Y)
      }
    }

    // The items owned, the one on B framed
    drawFrame(context, 120, 48, 13, 6)
    inventory.bItems.forEach((bItem, index) => {
      const x = SLOTS_X + (index % SLOTS_PER_LINE) * SLOT_WIDTH
      const y = SLOTS_Y + Math.floor(index / SLOTS_PER_LINE) * SLOT_HEIGHT
      // The arrow and the bow are shown even when Link only has one of them
      const name = index === BOW_SLOT ? (inventory.arrow === ARROW_SILVER ? ITEM_SILVER_ARROW : inventory.arrow ? ITEM_WOODEN_ARROW : undefined) : bItem
      if (index === BOW_SLOT && inventory.bow) {
        drawItem(context, ITEM_BOW, x + BOW_SHIFT, y)
      }
      if (!name) {
        return
      }
      drawItem(context, name, index === BOW_SLOT ? x - BOW_SHIFT : x, y)
      if (index === this.selection) {
        for (const [corner, dx, dy] of [['north_west', -4, 0], ['north_east', 4, 0], ['south_west', -4, 8], ['south_east', 4, 8]]) {
          resource.getSprite(`menu_select_corner_${corner}`)?.draw(context, (x + dx) * SCALE, (y + dy) * SCALE, TILE, TILE)
        }
      }
    })

    this.drawTriforce(context)
    context.restore()
  }
}

export { InventoryMenu }
