'use strict'

import resource from '../resource'
import { GAME_WIDTH, GAME_HEIGHT } from '../constant'

const STORAGE_SIZE = 'loz-screen-size'
const STORAGE_PACK = 'loz-graphics-pack'
const SIZE_FIT = 'fit'
// What the page keeps around the canvas when it fits the window, in CSS pixels
const MARGIN_WIDTH = 20
const MARGIN_HEIGHT = 60
const MIN_SIZE = 0.25
// The settings beside the game (wide window, not a touch screen) when the game stays at least this big compared
// with the settings under it, out of sight: width they take (with the gap, see index.scss)
const SIDE_CONTROLS_WIDTH = 340
const SIDE_CONTROLS_MIN_RATIO = 0.85
const SIDE_CONTROLS_CLASS = 'side-controls'
// Keys that scroll the page: not while playing
const SCROLL_KEYS = ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space', 'PageUp', 'PageDown']

function read (key, fallback) {
  try {
    return window.localStorage.getItem(key) ?? fallback
  } catch (e) {
    return fallback
  }
}

function write (key, value) {
  try {
    window.localStorage.setItem(key, value)
  } catch (e) {}
}

// The size of the screen (fit the window, or 1, 2, 3 times the game) and the graphics pack, chosen in the page.
// The canvas has as many pixels as it shows (screens with dense pixels too): the game is drawn in its own display
// pixels (GAME_WIDTH × GAME_HEIGHT), scaled, so that fine graphics keep their details
export class Display {
  // touch: the pad of the touch screens (see touch-controls.js), the game fits beside it
  constructor (canvas, context, sizeSelect, packSelect, touch) {
    this.touch = touch
    this.canvas = canvas
    this.context = context
    this.sizeSelect = sizeSelect
    this.packSelect = packSelect
    this.size = read(STORAGE_SIZE, SIZE_FIT)
    this.scale = 1
    this.width = GAME_WIDTH
    this.height = GAME_HEIGHT
  }

  async init () {
    if (this.sizeSelect) {
      this.sizeSelect.value = this.size
      this.sizeSelect.addEventListener('change', () => this.setSize(this.sizeSelect.value))
    }
    window.addEventListener('resize', () => this.resize())
    document.addEventListener('keydown', e => {
      const typing = ['INPUT', 'SELECT', 'TEXTAREA'].includes(e.target?.tagName)
      if (!typing && SCROLL_KEYS.includes(e.code)) {
        e.preventDefault()
      }
    })
    this.resize()
    await this.initPacks()
  }

  setSize (size) {
    this.size = size
    write(STORAGE_SIZE, size)
    this.resize()
    this.canvas.focus()
  }

  // Size on the page (CSS pixels), then pixels of the canvas
  resize () {
    const reserved = this.touch?.reserved ?? { width: 0, height: 0 }
    const margin = this.touch?.active ? { width: 0, height: 0 } : { width: MARGIN_WIDTH, height: MARGIN_HEIGHT }
    const fitIn = width => Math.min((width - margin.width - reserved.width) / GAME_WIDTH, (window.innerHeight - margin.height - reserved.height) / GAME_HEIGHT)
    let fit = fitIn(window.innerWidth)
    const side = !this.touch?.active && fitIn(window.innerWidth - SIDE_CONTROLS_WIDTH) >= fit * SIDE_CONTROLS_MIN_RATIO
    document.body.classList.toggle(SIDE_CONTROLS_CLASS, side)
    if (side) {
      fit = fitIn(window.innerWidth - SIDE_CONTROLS_WIDTH)
    }
    const size = this.size === SIZE_FIT ? Math.max(MIN_SIZE, fit) : Number(this.size) || 1
    const ratio = window.devicePixelRatio || 1
    this.canvas.style.width = `${Math.round(GAME_WIDTH * size)}px`
    this.canvas.style.height = `${Math.round(GAME_HEIGHT * size)}px`
    this.canvas.width = Math.round(GAME_WIDTH * size * ratio)
    this.canvas.height = Math.round(GAME_HEIGHT * size * ratio)
    this.scale = this.canvas.width / GAME_WIDTH
  }

  // Before drawing a frame: the drawing in display pixels of the game, scaled to the canvas
  prepare () {
    this.context.setTransform(this.scale, 0, 0, this.scale, 0, 0)
  }

  async initPacks () {
    const packs = await resource.loadPackList()
    for (const pack of packs) {
      const option = document.createElement('option')
      option.value = pack.id
      option.textContent = pack.name
      this.packSelect?.append(option)
    }
    this.packSelect?.addEventListener('change', () => this.usePack(this.packSelect.value))
    const saved = read(STORAGE_PACK, '')
    if (saved && packs.some(pack => pack.id === saved)) {
      await this.usePack(saved)
    }
  }

  // Switched at once, even in the middle of a game; '' for the original graphics
  async usePack (id) {
    try {
      resource.usePack(id ? await resource.loadPack(id) : undefined)
      write(STORAGE_PACK, id)
      if (this.packSelect) {
        this.packSelect.value = id
      }
    } catch (e) {
      console.error(`Graphics pack ${id}: ${e.message}`)
      resource.usePack(undefined)
      if (this.packSelect) {
        this.packSelect.value = ''
      }
    }
    this.canvas.focus()
  }
}
