'use strict'

import resource from '../resource'
import { overlaps } from '../utils/box'
import { directionOf, enemyReached, bladeCentre, boomerangCentre, REACH_ARROW, REACH_BEAM, REACH_BOOMERANG } from './enemies/common'
import { Flame } from './flame'
import { TILE_WIDTH, TILE_HEIGHT, NES_PIXEL, ITEM_MAGICAL_BOOMERANG, ARROW_SILVER } from '../constant'

// What Link throws, shoots or puts down with B, besides bombs and flames: each in map.weapons, one of a kind at a
// time. Measured in the ROM, Link in the middle of the screen 7,7, B pressed (see docs/rom-analysis.md). All start
// one tile in front of Link. Speeds in display pixels a game step (twice the NES pixels a frame)

const DIRECTION_VECTORS = { east: [1, 0], west: [-1, 0], north: [0, -1], south: [0, 1] }

// Off the screen, or about to be
function isOut (map, box) {
  return box.x < map.x || box.y < map.y || box.x + box.width > map.x + map.width || box.y + box.height > map.y + map.height
}

// What hits the enemies: the middle of the tile, across the way it goes
function bladeBox (x, y, [dx]) {
  return dx !== 0
    ? { x, y: y + TILE_HEIGHT / 4, width: TILE_WIDTH, height: TILE_HEIGHT / 2 }
    : { x: x + TILE_WIDTH / 4, y, width: TILE_WIDTH / 2, height: TILE_HEIGHT }
}

// Their sprites from their places, as the ROM draws them: an arrow up or down at its place, its picture being in
// the middle of the tile; an arrow or the magic sideways 3 NES pixels lower
function spriteOffset (direction, { vertical = [0, 0], sideways = [0, 3] } = {}) {
  const [x, y] = direction === 'north' || direction === 'south' ? vertical : sideways
  return [x * NES_PIXEL, y * NES_PIXEL]
}

function drawImage (context, name, index, x, y) {
  const sprite = resource.getSprite(name)
  const images = sprite?.images
  const image = images?.length ? images[index % images.length] : sprite
  image?.draw(context, x, y, TILE_WIDTH, TILE_HEIGHT)
}

// Boomerang (object $0F): the wooden one flies 3 NES pixels a frame for 17 frames, then 1 pixel a frame for 16
// frames, turns, comes back 1 pixel a frame for 16 frames, then 2 pixels a frame straight to Link. The magical one
// flies 3 pixels a frame as far as the edge of the screen, waits 2 frames there, then comes back 2 pixels a frame.
// It stuns the enemy it hits (no damage) and comes back; it brings back what the enemies left
const BOOMERANG_FAST = 3 * NES_PIXEL
const BOOMERANG_FAST_STEPS = 17
const BOOMERANG_SLOW = NES_PIXEL
const BOOMERANG_SLOW_STEPS = 16
const BOOMERANG_BACK = 2 * NES_PIXEL
const BOOMERANG_EDGE_STEPS = 2
// It spins, a quarter every 2 frames (states $10 to $17)
const BOOMERANG_FRAME_STEPS = 2

export class Boomerang {
  constructor (x, y, direction, name) {
    this.x = x
    this.y = y
    this.vector = DIRECTION_VECTORS[direction]
    this.magical = name === ITEM_MAGICAL_BOOMERANG
    this.steps = 0
    // Out, slow (the wooden one), waiting at the edge, slow back (the wooden one), back to Link
    this.phase = 'out'
    this.phaseSteps = 0
    this.carried = []
    this.done = false
  }

  setPhase (phase) {
    this.phase = phase
    this.phaseSteps = 0
  }

  getBox () {
    return { x: this.x + TILE_WIDTH / 4, y: this.y + TILE_HEIGHT / 4, width: TILE_WIDTH / 2, height: TILE_HEIGHT / 2 }
  }

  get returning () {
    return this.phase === 'slow_back' || this.phase === 'back'
  }

  // Stopped at the edge of the screen: true when it got there
  moveBy (map, distance, [dx, dy]) {
    this.x = Math.max(map.x, Math.min(map.x + map.width - TILE_WIDTH, this.x + dx * distance))
    this.y = Math.max(map.y, Math.min(map.y + map.height - TILE_HEIGHT, this.y + dy * distance))
    return isOut(map, { x: this.x + dx, y: this.y + dy, width: TILE_WIDTH, height: TILE_HEIGHT })
  }

  // Straight to Link, along both axes
  homeIn (link) {
    const dx = link.x - this.x
    const dy = link.y - this.y
    const distance = Math.hypot(dx, dy)
    if (distance <= BOOMERANG_BACK) {
      this.x = link.x
      this.y = link.y
      return true
    }
    this.x += Math.round(dx / distance * BOOMERANG_BACK)
    this.y += Math.round(dy / distance * BOOMERANG_BACK)
    return false
  }

  process (map, link) {
    this.steps++
    this.phaseSteps++
    switch (this.phase) {
      case 'out':
        if (this.moveBy(map, BOOMERANG_FAST, this.vector)) {
          this.setPhase('edge')
        } else if (!this.magical && this.phaseSteps >= BOOMERANG_FAST_STEPS) {
          this.setPhase('slow')
        }
        break
      case 'slow':
        if (this.moveBy(map, BOOMERANG_SLOW, this.vector)) {
          this.setPhase('edge')
        } else if (this.phaseSteps >= BOOMERANG_SLOW_STEPS) {
          this.setPhase('slow_back')
        }
        break
      case 'edge':
        if (this.phaseSteps >= BOOMERANG_EDGE_STEPS) {
          this.setPhase('back')
        }
        break
      case 'slow_back':
        this.moveBy(map, -BOOMERANG_SLOW, this.vector)
        if (this.phaseSteps >= BOOMERANG_SLOW_STEPS) {
          this.setPhase('back')
        }
        break
      case 'back':
        if (this.homeIn(link)) {
          // Caught: what it brought back is Link's, and he takes the pose again
          for (const drop of this.carried.filter(drop => !drop.done)) {
            drop.give(map, link)
            drop.done = true
          }
          link.catchBoomerang?.()
          this.done = true
          return
        }
    }
    const box = this.getBox()
    if (!this.returning && this.phase !== 'edge') {
      const enemy = enemyReached(map, boomerangCentre(this.x, this.y), REACH_BOOMERANG)
      if (enemy) {
        enemy.stun(link)
        this.setPhase('back')
      }
    }
    for (const drop of map.drops) {
      if (!drop.done && !this.carried.includes(drop) && overlaps(box, drop.getBox())) {
        this.carried.push(drop)
        if (!this.returning) {
          this.setPhase('back')
        }
      }
    }
    for (const drop of this.carried) {
      drop.x = this.x
      drop.y = this.y
    }
  }

  draw (context) {
    drawImage(context, `boomerang_${this.magical ? 'magical' : 'wooden'}`, Math.floor(this.steps / BOOMERANG_FRAME_STEPS), this.x, this.y)
  }
}

// Arrow (object $12): 3 NES pixels a frame, it costs a rupee. The wooden one hits as hard as the white sword, the
// silver one as the magical sword. It stops on the first enemy it hits; at the edge of the screen, it ends in a
// spark for 3 frames
const ARROW_SPEED = 3 * NES_PIXEL
export const ARROW_DAMAGES = { wooden: 2, silver: 4 }
const ARROW_END_STEPS = 3

export class Arrow {
  constructor (x, y, direction, arrow) {
    this.x = x
    this.y = y
    this.direction = direction
    this.vector = DIRECTION_VECTORS[direction]
    this.kind = arrow === ARROW_SILVER ? 'silver' : 'wooden'
    this.endSteps = undefined
    this.done = false
  }

  getBox () {
    return bladeBox(this.x, this.y, this.vector)
  }

  process (map, link) {
    if (this.endSteps !== undefined) {
      this.endSteps++
      this.done = this.endSteps >= ARROW_END_STEPS
      return
    }
    this.x += this.vector[0] * ARROW_SPEED
    this.y += this.vector[1] * ARROW_SPEED
    const box = this.getBox()
    if (isOut(map, box)) {
      this.x -= this.vector[0] * ARROW_SPEED
      this.y -= this.vector[1] * ARROW_SPEED
      this.endSteps = 0
      return
    }
    const enemy = enemyReached(map, bladeCentre(this.x, this.y, link.direction), REACH_ARROW)
    if (enemy) {
      enemy.hit(link, { damage: ARROW_DAMAGES[this.kind], direction: directionOf(enemy.x - this.x, enemy.y - this.y) })
      this.done = true
    }
  }

  draw (context) {
    if (this.endSteps !== undefined) {
      drawImage(context, 'arrow_end', 0, this.x, this.y)
      return
    }
    const [dx, dy] = spriteOffset(this.direction, { vertical: [-4, 0] })
    drawImage(context, `arrow_${this.kind}_${this.direction}`, 0, this.x + dx, this.y + dy)
  }
}

// Magic of the wand (object $0E): it comes out a tile in front of Link as the wand is drawn back, then goes 3, 2,
// 3, 2… NES pixels a frame, changing palette every frame; it hits as hard as the white sword and stops on the first
// enemy. With the book of magic, a flame burns where it stops (79 frames, measured on a frozen octorok)
const MAGIC_STEPS = [3, 2]
export const MAGIC_DAMAGE = 2
export const BOOK_FLAME_STEPS = 79

export class Magic {
  constructor (x, y, direction, book) {
    this.x = x
    this.y = y
    this.direction = direction
    this.vector = DIRECTION_VECTORS[direction]
    this.book = book
    this.steps = 0
    this.done = false
  }

  getBox () {
    return bladeBox(this.x, this.y, this.vector)
  }

  end (map) {
    this.done = true
    if (this.book) {
      map.flames.push(new Flame(Math.round(this.x), Math.round(this.y), [0, 0], { moveSteps: 0, burnSteps: BOOK_FLAME_STEPS }))
    }
  }

  // The frame it comes out, it stays at its place
  process (map, link) {
    const speed = this.steps === 0 ? 0 : MAGIC_STEPS[(this.steps - 1) % 2] * NES_PIXEL
    this.steps++
    this.x += this.vector[0] * speed
    this.y += this.vector[1] * speed
    const box = this.getBox()
    if (isOut(map, box)) {
      this.x -= this.vector[0] * speed
      this.y -= this.vector[1] * speed
      this.end(map)
      return
    }
    const enemy = enemyReached(map, bladeCentre(this.x, this.y, link.direction), REACH_BEAM)
    if (enemy) {
      enemy.hit(link, { damage: MAGIC_DAMAGE, direction: directionOf(enemy.x - this.x, enemy.y - this.y) })
      this.end(map)
    }
  }

  draw (context) {
    const [dx, dy] = spriteOffset(this.direction)
    drawImage(context, `magic_${this.direction}`, this.steps, this.x + dx, this.y + dy)
  }
}

// Bait (object $0F, state $80): it stays where Link put it 3 times 255 frames (754 measured), and the enemies go
// after it instead of Link (bank 7, $F4A0: it becomes their target). It is not used up on the overworld
export const BAIT_STEPS = 754

export class Bait {
  constructor (x, y) {
    this.x = x
    this.y = y
    this.steps = 0
    this.done = false
  }

  process (map) {
    this.steps++
    map.target = { x: this.x, y: this.y }
    this.done = this.steps >= BAIT_STEPS
  }

  draw (context) {
    drawImage(context, 'bait', 0, this.x, this.y)
  }
}
